  String depositPath="/clubs/"+cid+"/reserve/entries/"+text(deposit,"id");var sent=post(depositPath+"/sent",owner,Map.of("version",version(deposit),"reference","deposit-transfer","actualAt",Instant.now().toString()));assertEquals(200,sent.status);
  var confirmed=post(depositPath+"/confirm",owner,Map.of("version",version(sent),"reference","deposit-bank-receipt","actualAt",Instant.now().toString()));assertEquals(200,confirmed.status);assertEquals(1000,confirmed.body.path("balance").asLong());
  var spend=post("/clubs/"+cid+"/reserve/spends",owner,Map.of("version",version(confirmed),"amount",400,"purpose","모임 물품 구입"));assertEquals(200,spend.status);assertEquals(1000,spend.body.path("balance").asLong());
  assertEquals(409,post("/clubs/"+cid+"/reserve/spends",owner,Map.of("version",version(spend),"amount",700,"purpose","초과 사용" )).status);
  var spent=post("/clubs/"+cid+"/reserve/entries/"+text(spend,"id")+"/execute",owner,Map.of("version",version(spend),"reference","actual-outgoing","actualAt",Instant.now().toString()));assertEquals(200,spent.status);assertEquals(600,spent.body.path("balance").asLong());
  var payout=post("/clubs/"+cid+"/dissolution/payout",owner,Map.of("version",version(spent)));assertEquals(200,payout.status);assertEquals(600,payout.body.path("balance").asLong());
